BEGIN;
SET LOCAL app.is_platform = 'on';
CREATE TEMP TABLE r ON COMMIT DROP AS SELECT id FROM restaurants WHERE name ILIKE '%chupacabra%';
DO $$ BEGIN IF (SELECT count(*) FROM r) <> 1 THEN RAISE EXCEPTION 'Se esperaba 1 restaurante Chupacabras, hay %', (SELECT count(*) FROM r); END IF;
IF EXISTS (SELECT 1 FROM menu_items WHERE restaurant_id=(SELECT id FROM r)) THEN RAISE EXCEPTION 'El Chupacabras ya tiene productos; no se carga nada'; END IF; END $$;
CREATE TEMP TABLE g (k text, id uuid) ON COMMIT DROP;
