WITH x AS (INSERT INTO menu_items (restaurant_id,category_id,name,description,price,sort_order) SELECT r.id,c.id,'Agua',NULL,25,0 FROM r, c WHERE c.n='Bebidas' RETURNING id) INSERT INTO it SELECT id,false,NULL FROM x;
WITH x AS (INSERT INTO menu_items (restaurant_id,category_id,name,description,price,sort_order) SELECT r.id,c.id,'Soda',NULL,30,1 FROM r, c WHERE c.n='Bebidas' RETURNING id) INSERT INTO it SELECT id,false,NULL FROM x;
WITH x AS (INSERT INTO menu_items (restaurant_id,category_id,name,description,price,sort_order) SELECT r.id,c.id,'Té de Litro',NULL,40,2 FROM r, c WHERE c.n='Bebidas' RETURNING id) INSERT INTO it SELECT id,false,NULL FROM x;
INSERT INTO menu_item_modifier_groups (restaurant_id,menu_item_id,modifier_group_id,sort_order) SELECT (SELECT id FROM r), it.id, g.id, 0 FROM it JOIN g ON g.k=it.grp;
INSERT INTO menu_item_modifier_groups (restaurant_id,menu_item_id,modifier_group_id,sort_order) SELECT (SELECT id FROM r), it.id, g.id, 1 FROM it JOIN g ON g.k='sin' WHERE it.burger;
INSERT INTO menu_item_modifier_groups (restaurant_id,menu_item_id,modifier_group_id,sort_order) SELECT (SELECT id FROM r), it.id, g.id, 2 FROM it JOIN g ON g.k='extras' WHERE it.burger;
SELECT (SELECT count(*) FROM c) categorias, (SELECT count(*) FROM it) productos, (SELECT count(*) FROM g) grupos, (SELECT count(*) FROM menu_item_modifier_groups WHERE restaurant_id=(SELECT id FROM r)) enlaces;
COMMIT;
